The water turns darker, because the surface only uses the light value of the water block itself.
In vanilla, if the block above is brighter than the water, the brightness value of that block is used instead.

I fixed the issue with these 2 mixins:
```java
@Mixin(value = FluidRendererImpl.class)
public class FluidRendererImplMixin {

	@Inject(method = "render", at = @At("HEAD"))
	private void beforeRender(LevelSlice level, BlockState blockState, FluidState fluidState, BlockPos blockPos, BlockPos offset, TranslucentGeometryCollector collector, ChunkBuildBuffers buffers, CallbackInfo ci) {
		renderingLiquid.set(true);
	}

	@Inject(method = "render", at = @At("TAIL"))
	private void afterRender(LevelSlice level, BlockState blockState, FluidState fluidState, BlockPos blockPos, BlockPos offset, TranslucentGeometryCollector collector, ChunkBuildBuffers buffers, CallbackInfo ci, @Local FluidRenderHandler fluidRenderHandler) {
		renderingLiquid.set(false);
	}
}
```
```java
@Mixin(value = FlatLightPipeline.class)
public class FlatLightPipelineMixin {

	@Shadow
	private LightDataAccess lightCache;

	@Inject(method = "calculate", at = @At("TAIL"))
	private void afterCalculate(ModelQuadView quad, BlockPos pos, QuadLightData out, Direction cullFace, Direction lightFace, boolean shade, boolean enhanced, CallbackInfo ci) {
		Boolean b = renderingLiquid.get();
		if(lightFace != Direction.UP || b == null || !b) {
			return;
		}

		int lightmap = LightDataAccess.getEmissiveLightmap(lightCache.get(pos));
		int lightmapAbove = LightDataAccess.getEmissiveLightmap(lightCache.get(pos.getX(), pos.getY() + 1, pos.getZ()));
		int maxLightmap = ColorHelper.maxBrightness(lightmap, lightmapAbove);
		Arrays.fill(out.lm, maxLightmap);
	}

}
